cc7203b fix(yazi): patch mdv-previewer for mdv's renamed style flags
mdv master (WhoSowSee/mdv@556d839) renamed --pretty-list,
--pretty-checkbox, --pretty-definition and --pretty-table to
--list-style, --checkbox-style, --definition-marker-style and
--table-borders without bumping its 5.1.0 version. mdv-previewer.yazi
only tracks mdv releases, so its default args made every Markdown
preview fail with "unexpected argument '--pretty-list'".

Rename the flags in the plugin's main.lua via applyPatches. The
substitutions use --replace-fail, so the build breaks once the plugin
catches up, which is the cue to drop the patch.


 home/home.nix | 17 ++++++++++++++++-
 1 file changed, 16 insertions(+), 1 deletion(-)
=== patch diff ===
diff --git a/home/home.nix b/home/home.nix
index aba9ce7..b341555 100644
--- a/home/home.nix
+++ b/home/home.nix
@@ -254,7 +254,22 @@ in {
   programs.yazi = {
     enable = true;
     extraPackages = [ mdv ];
-    plugins.mdv-previewer = inputs.mdv-previewer;
+    # mdv master renamed its --pretty-* styling flags (WhoSowSee/mdv@556d839),
+    # but the plugin's default args still use the v5.1.0 release names, so every
+    # preview failed with "unexpected argument '--pretty-list'". --replace-fail
+    # breaks the build once the plugin catches up: that's the cue to drop this
+    # and go back to plain `inputs.mdv-previewer`.
+    plugins.mdv-previewer = pkgs.applyPatches {
+      name = "mdv-previewer.yazi";
+      src = inputs.mdv-previewer;
+      postPatch = ''
+        substituteInPlace main.lua \
+          --replace-fail '"--pretty-list"' '"--list-style"' \
+          --replace-fail '"--pretty-checkbox"' '"--checkbox-style"' \
+          --replace-fail '"--pretty-definition"' '"--definition-marker-style"' \
+          --replace-fail '"--pretty-table"' '"--table-borders"'
+      '';
+    };
     settings.plugin = {
       prepend_previewers = [
         { url = "*.{md,markdown,txt}"; run = "mdv-previewer"; }
=== current code ===
home/home.nix-258-    # but the plugin's default args still use the v5.1.0 release names, so every
home/home.nix-259-    # preview failed with "unexpected argument '--pretty-list'". --replace-fail
home/home.nix-260-    # breaks the build once the plugin catches up: that's the cue to drop this
home/home.nix:261:    # and go back to plain `inputs.mdv-previewer`.
home/home.nix:262:    plugins.mdv-previewer = pkgs.applyPatches {
home/home.nix:263:      name = "mdv-previewer.yazi";
home/home.nix:264:      src = inputs.mdv-previewer;
home/home.nix-265-      postPatch = ''
home/home.nix-266-        substituteInPlace main.lua \
home/home.nix-267-          --replace-fail '"--pretty-list"' '"--list-style"' \
home/home.nix-268-          --replace-fail '"--pretty-checkbox"' '"--checkbox-style"' \
home/home.nix-269-          --replace-fail '"--pretty-definition"' '"--definition-marker-style"' \
home/home.nix-270-          --replace-fail '"--pretty-table"' '"--table-borders"'
home/home.nix-271-      '';
home/home.nix-272-    };
home/home.nix-273-    # Parent and current columns kept equal and narrow so the preview gets two
home/home.nix-274-    # thirds of the width: in the code layout yazi only has the right column.
home/home.nix-275-    settings.mgr.ratio = [ 1 1 4 ];
home/home.nix-276-    settings.plugin = {
home/home.nix-277-      prepend_previewers = [
home/home.nix:278:        { url = "*.{md,markdown,txt}"; run = "mdv-previewer"; }
home/home.nix-279-      ];
home/home.nix-280-      prepend_preloaders = [
home/home.nix:281:        { url = "*.{md,markdown,txt}"; run = "mdv-previewer"; }
home/home.nix-282-      ];
home/home.nix-283-    };
home/home.nix-284-  };
home/home.nix-285-
home/home.nix-286-  home.file = lib.optionalAttrs (!isMinimal) mcp.agyExtensionFiles;
