home/home.nix-303-        || cp "$managed" "$settings.new"
home/home.nix-304-    else
home/home.nix-305-      cp "$managed" "$settings.new"
home/home.nix-306-    fi
flake.nix-19-      url = "github:WhoSowSee/mdv";
flake.nix-20-      inputs.nixpkgs.follows = "nixpkgs";
flake.nix-21-    };
flake.nix:22:    mdv-previewer = {
